<script setup lang="ts">
import MemberTasksSection from '@/ui/components/MemberTasksSection.vue';
import {computed,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useChatStore} from '@/store/chat';import {useSessionStore} from '@/session/store';import {communication} from '@/api/endpoints';import type {ChatMessage} from '@/api/types';import MemberAvatar from '@/ui/components/MemberAvatar.vue';import PageHeading from '@/ui/components/PageHeading.vue';import {presenceStatus} from '@/chat/presence';import {useReadFeedback} from '@/ui/useReadFeedback';
const route=useRoute(),router=useRouter(),chat=useChatStore(),session=useSessionStore();const actor=computed(()=>String(route.params.actor||'')),member=computed(()=>chat.members.find(m=>m.username===actor.value));const older=ref<number|undefined>(undefined),hasOlder=ref(false);
const {error,feedback}=useReadFeedback({retry:()=>loadMessages(),ready:()=>session.businessReady});
const messages=ref<ChatMessage[]>([]),open=ref(false),busy=ref(false);let generation=0;
watch(actor,async id=>{generation++;messages.value=[];older.value=undefined;hasOlder.value=false;busy.value=false;open.value=false;feedback.succeeded();if(id===session.user?.username){void router.replace({name:'profile'});return;}await chat.refreshMembers();},{immediate:true});
async function showMessages(){open.value=!open.value;if(!open.value||messages.value.length||busy.value)return;await loadMessages();}
async function loadMessages(){if(busy.value)return;const n=generation,owner=session.user?.username;busy.value=true;feedback.begin(messages.value.length>0);try{const page=await communication.messages({author:actor.value,before:older.value,limit:50});if(n===generation&&owner===session.user?.username){messages.value=[...messages.value,...page.messages.filter(m=>!m.hidden).reverse()];older.value=page.oldest_cursor;hasOlder.value=!!page.has_more_old;feedback.succeeded();}}catch(e){if(n===generation&&owner===session.user?.username){if([401,403].includes((e as any)?.status))messages.value=[];feedback.failed(e,'消息暂未读取，请重试');}}finally{if(n===generation)busy.value=false;}}
</script>
<template><div class="member-page"><PageHeading title="成员主页"/><section v-if="member" class="member-hero"><MemberAvatar preview :actor="actor" :name="member.nickname" :size="64"/><div><h2>{{member.nickname}}</h2><small>{{presenceStatus(member)}}</small></div></section><p v-else class="field-help">{{chat.memberError||'该成员当前不可查看'}}</p><template v-if="member"><button class="btn primary" @click="router.push({name:'chat',query:{peer:actor}})">发消息</button><MemberTasksSection :actor="actor"/><button class="member-messages" :aria-expanded="open" @click="showMessages">群内消息 <span>{{open?'⌃':'⌄'}}</span></button><section v-if="open"><p v-if="error" role="alert">{{error}}<button class="btn small" :disabled="busy" @click="loadMessages">重试读取消息</button></p><p v-if="busy">正在读取消息…</p><p v-else-if="!messages.length&&!error" class="field-help">暂无群内消息</p><button v-for="m in messages" :key="m.id" class="member-message" @click="router.push({name:'chat',query:{message:m.id}})">{{m.recalled?'消息已撤回':m.body||m.attachments.map(a=>a.mime.startsWith('image/')?'[图片]':a.purpose==='voice'?'[语音]':'[文件] '+a.name).join(' ')}}</button><button v-if="hasOlder" class="btn small" :disabled="busy" @click="loadMessages">查看更早消息</button></section></template></div></template>
<style scoped>.member-page{padding:12px}.member-hero{display:flex;gap:16px;align-items:center;margin:18px 0 24px}.member-hero h2{font-size:18px;margin-bottom:8px}.member-hero small{font-size:12px;color:var(--muted)}.member-page>.primary{width:100%;margin-bottom:24px}.member-messages,.member-message{width:100%;text-align:left;padding:14px 4px;background:transparent;border:0;border-bottom:1px solid var(--line);font-size:14px;color:var(--ink);overflow-wrap:anywhere}.member-messages{display:flex;justify-content:space-between}.member-message:active{background:var(--green-soft)}</style>
